INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62553672', 62553672, 'analyze_legacy', 'Kota Madiun', 'kabkota', 'Dinas Perumahan Rakyat dan Kawasan Permukiman', 'Belanja Pakan Ternak', 'Barang', 'Pengadaan Langsung', 'Jawa Timur, Madiun (Kota)', 34776000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Pakan Ternak', 'Pengadaan Barang', 34776000, 'high', 'Pengadaan pakan ternak oleh perangkat daerah yang berfokus pada perumahan rakyat dan kawasan permukiman tampak tidak selaras dengan fungsi utamanya. Dari judul item, kebutuhan ini terindikasi tidak relevan dengan tugas organisasi sehingga seluruh nilai pengadaan layak dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 516479);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65629476', 65629476, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Pemeliharaan Alat Kesehatan/Kedokteran/Alat Penunjang Medik Lainnya', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 714040051, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Pengadaan jasa lainnya berupa perawatan preventif dan korektif untuk menjaga alat medis tetap berfungsi optimal, aman, dan memenuhi standar pelayanan kesehatan. Pekerjaan meliputi pemeriksaan berkala, pembersihan, kalibrasi, penggantian suku cadang yang aus, perbaikan kerusakan ringan hingga sedang, serta uji fungsi setelah perbaikan, yang dilaksanakan selama tahun anggaran berjalan guna menjamin keselamatan pasien dan keberlangsungan operasional pelayanan medis.', 'Pelaksanaan pemeliharaan preventif dan korektif sesuai standar pabrikan dan regulasi alat kesehatan, termasuk pemeriksaan rutin, pembersihan, kalibrasi, pengujian keselamatan listrik, serta penggantian suku cadang dengan komponen baru dan berkualitas setara asli. Pekerjaan harus dilakukan oleh teknisi kompeten/bersertifikat, disertai uji fungsi hingga alat beroperasi normal, serta dilengkapi laporan servis, sertifikat kalibrasi (apabila diperlukan), dan berita acara sebagai dasar pembayaran dan pengendalian aset medis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 516480);
