INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63030558', 63030558, 'analyze_legacy', 'Perpustakaan Nasional Republik Indonesia', 'central', 'PERPUSTAKAAN NASIONAL RI JAKARTA', 'Annual Technical Support / ATS Perangkat Security Network (Firewall) Data Center Perpustakaan Nasional Republik Indonesia', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1975000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 Paket', '1. Menyelenggarakan kick of meeting dengan tim Pusat Data dan Informasi dan pihak terkait di Perpustakaan Nasional Republik Indonesia; 2. Berkomunikasi dengan pihak principle perangkat keras yang akan dilanjutkan perpanjangan lisensinya sesuai dengan spesifikasi teknis dalam dokumen ini; 3. Menyerahkan dokumen lisensi atau bukti perpanjangan lisensi dalam bentuk hardcopy dan softcopy; 4. Memastikan kegiatan technical support dari pihak pemegang lisensi dilaksanakan sebagai mana mestinya sesuai dengan masa berlaku lisensi; 5. Siap untuk dihubungidan datang dalam waktu 7x24 jam ke Gedung Perpustakaan Nasional Republik Indonesia apabila terjadi permasalahan terhadap perangkat keras yang diperpanjang lisensinya sesuaidengan spesifikasi teknis dalam dokumen; 6. Menyelenggarakan rapat review progres pelaksanaan pekerjaan; 7. Memberikan pelatihan kepada tim Pusat Data dan informasi terkait perangkat yang di perpanjang renewal lisensinya seperti setting, konfigurasi dan treatment yang dilakukan apabila terjadi masalah pada perangkat; 8. Membuat laporan pelaksanaan pekerjaan; 9. Membuat dokumen berita acara serah terima hasil pekerjaan.', 'a. Dukungan penggantian unit dengan SLA 24x7 on call standby selama 12 bulan dan sesuai dengan masa berlaku ATS masing-masing perangkat (end of date); b. Dukungan backup unit dengan SLA 24x7 on call standby selama 12 bulan dan sesuai dengan masa berlaku ATS masing-masing perangkat (end of date); c. Dukungan tenaga teknis dengan SLA 24x7 on call standby selama 12 bulan dan sesuai dengan masa berlaku ATS masing-masing perangkat (end of date); d. Online customer support center selama 12 bul an dan sesuaidengan masa berlaku ATS masing-masing perangkat (end of date); e. Patching firmware selama 12 bulan dan sesuaidengan masa berlaku ATS masing-masing perangkat (end of date).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 518374);
