INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63052374', 63052374, 'analyze_legacy', 'Kota Balikpapan', 'kabkota', 'UPTD-RUMAH SAKIT UMUM DAERAH', 'Penyediaan Jasa Perizinan Kendaraan Dinas/Operasional', 'Jasa Lainnya', 'Dikecualikan', 'Kalimantan Timur, Balikpapan (Kota)', 50000000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Kegiatan ini meliputi pengelolaan dan penyelesaian seluruh proses perizinan kendaraan dinas/operasional rumah sakit agar kendaraan tetap legal dan layak digunakan. Prosesnya mencakup pengurusan perpanjangan STNK dan BPKB, pembayaran pajak kendaraan bermotor, pengurusan dokumen administratif lain yang diwajibkan oleh peraturan, serta koordinasi dengan instansi terkait seperti Samsat. Kegiatan ini dilakukan untuk memastikan kendaraan dinas/operasional selalu memenuhi ketentuan hukum, mendukung kelancaran pelayanan dan penunjang pelayanan RSUD Beriman Balikpapan, dan mengurangi risiko hukum atau administratif', 'Kegiatan ini meliputi jasa pengurusan seluruh perizinan kendaraan dinas/operasional sesuai peraturan yang berlaku, termasuk perpanjangan STNK, BPKB, dan pembayaran pajak kendaraan bermotor. Spesifikasi pekerjaan mencakup pengecekan kelengkapan dokumen, pengisian formulir resmi, koordinasi dengan instansi berwenang (Samsat/Dispenda), pembayaran biaya resmi, serta penyerahan dokumen yang telah diurus. Seluruh pekerjaan harus dilakukan oleh tenaga yang berkompeten dan tepat waktu agar kendaraan selalu legal, layak jalan, dan siap digunakan untuk mendukung kelancaran pelayanan dan penunjang pelayanan RSUD Beriman Balikpapan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 518774);
