INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62101821', 62101821, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Pemeliharaan Printer Paspor Paper-Based Kegiatan Dukungan Penyelenggaraan Tugas dan Fungsi Unit pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 6500000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 Unit', 'Melakukan jasa pemeliharaan perangkat keras printer paspor SIMKIM untuk menjamin keberlangsungan pelayanan penerbitan paspor. Lingkup pekerjaan mencakup pelaksanaan perawatan preventif dan korektif (preventive & corrective maintenance) sesuai SLA, manajemen penggantian suku cadang (spare parts), pendataan inventaris perangkat di seluruh Kanim/ULP/Perwakilan, serta penyediaan layanan dukungan teknis 24/7 dan penyediaan petugas first layer support di lokasi layanan.', '1. Objek Pemeliharaan: Printer Paspor Datacard PB500 Gen2 (eksisting dan tambahan) yang tersebar di Kantor Imigrasi, Unit Layanan Paspor, dan Perwakilan/Atase Imigrasi. 2. Jenis Layanan: - Preventive: Perawatan berkala untuk mencegah kerusakan. - Corrective: Perbaikan dan penggantian suku cadang (spare parts) yang rusak. 3. Manajemen Layanan: - Layanan dukungan (Helpdesk) tersedia 24 jam x 7 hari (termasuk hari libur). - Tersedia sarana pelaporan (Telepon/Email) dan sistem ticketing untuk dokumentasi masalah. - Mekanisme eskalasi yang jelas untuk penanganan gangguan cepat. 4. SDM: Penyediaan petugas yang mampu menangani masalah sebagai first layer support di setiap titik layanan (Kanim/Perwakilan). 5. Output: Terjaminnya uptime perangkat, minimalisir downtime pelayanan, dan dokumentasi aset yang akurat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 519307);
